package io.github.astelev.around_planet.fuel;
import io.github.astelev.around_planet.propulsion.*;
/** Register missing base masses; read effective density for thrust without overriding Pondus accounting. */
public final class FuelMassBridge {
 private static java.lang.reflect.Method fluidEntry,blockEntry,registerFluid,registerBlock,fluidMass,inventoryMultiplier,globalInstance;
 private static java.lang.reflect.Constructor<?> fluidConstructor,blockConstructor;
 private static java.lang.reflect.Field fluidModifier;private static boolean initialized;
 public static double defaultKgPerBucket(boolean oxygen){return oxygen?Bipropellant.HYDROLOX.oxidizerKgPerMb()/Bipropellant.HYDROLOX.fuelKgPerMb():1;}
 public static void registerDefaults(){if(!pondus())return;var be=new PropulsionBlockEntity(net.minecraft.core.BlockPos.ZERO,PropulsionRegistry.LIQUID.get().defaultBlockState());kgPerMb(be,false);kgPerMb(be,true);}
 public static boolean pondus(){return net.neoforged.fml.ModList.get().isLoaded("pondus_inventory_fi");}
 private static void initialize(){if(initialized)return;try{String root="org.fractalinteractive.ci.pondus_inventory_fi.";var registry=Class.forName(root+"mass.MassRegistry");var fluid=Class.forName(root+"config.FluidMassEntry");var block=Class.forName(root+"config.BlockMassEntry");var global=Class.forName(root+"config.GlobalConfig");fluidEntry=registry.getMethod("getFluidMass",net.minecraft.world.level.material.Fluid.class);blockEntry=registry.getMethod("getBlockMass",net.minecraft.world.level.block.Block.class,net.minecraft.world.level.block.state.BlockState.class);registerFluid=registry.getMethod("registerFluid",String.class,fluid);registerBlock=registry.getMethod("registerBlock",String.class,block);fluidConstructor=fluid.getConstructor(String.class,String.class);blockConstructor=block.getConstructor(String.class,String.class,double.class,boolean.class);fluidMass=fluid.getMethod("getMass",int.class);inventoryMultiplier=block.getMethod("getInventoryMultiplier");globalInstance=global.getMethod("getInstance");fluidModifier=global.getField("fluidMassModifier");initialized=true;}catch(ReflectiveOperationException e){throw new IllegalStateException("Unsupported Pondus fuel mass API",e);}}
 public static double kgPerMb(PropulsionBlockEntity be,boolean oxygen){double nominal=defaultKgPerBucket(oxygen)/1000;if(!pondus())return nominal;initialize();try{var fluid=oxygen?CryogenicFluids.OXYGEN.get():CryogenicFluids.HYDROGEN.get();var entry=fluidEntry.invoke(null,fluid);if(entry==null){String id="around_planet:"+(oxygen?"liquid_oxygen":"liquid_hydrogen");registerFluid.invoke(null,id,fluidConstructor.newInstance(id,Double.toString(nominal*1000)));entry=fluidEntry.invoke(null,fluid);}var state=be.getBlockState();var block=blockEntry.invoke(null,state.getBlock(),state);if(block==null){String id="around_planet:liquid_rocket_engine";registerBlock.invoke(null,id,blockConstructor.newInstance(id,"200",1.0,true));block=blockEntry.invoke(null,state.getBlock(),state);}double mass=(double)fluidMass.invoke(entry,1)*fluidModifier.getDouble(globalInstance.invoke(null))*(double)inventoryMultiplier.invoke(block);return Double.isFinite(mass)&&mass>0?mass:0;}catch(ReflectiveOperationException e){throw new IllegalStateException("Cannot read Pondus propellant mass",e);}}
 public static double rsuKgPerMb(PropulsionBlockEntity be,net.minecraft.world.level.material.Fluid fluid){
  double nominal=Math.max(1,fluid.getFluidType().getDensity())/1_000_000.0;
  if(!pondus())return nominal;initialize();try{var entry=fluidEntry.invoke(null,fluid);if(entry==null){String id=net.minecraft.core.registries.BuiltInRegistries.FLUID.getKey(fluid).toString();registerFluid.invoke(null,id,fluidConstructor.newInstance(id,Double.toString(nominal*1000)));entry=fluidEntry.invoke(null,fluid);}var state=be.getBlockState();var block=blockEntry.invoke(null,state.getBlock(),state);if(block==null){String id="around_planet:rsu_distributor";registerBlock.invoke(null,id,blockConstructor.newInstance(id,"200",1.0,true));block=blockEntry.invoke(null,state.getBlock(),state);}double mass=(double)fluidMass.invoke(entry,1)*fluidModifier.getDouble(globalInstance.invoke(null))*(double)inventoryMultiplier.invoke(block);return Double.isFinite(mass)&&mass>0?mass:0;}catch(ReflectiveOperationException e){throw new IllegalStateException("Cannot read Pondus RSU fluid mass",e);}
 }
 public static double mass(PropulsionBlockEntity be){if(be.kind()==PropulsionRegistry.Kind.DISTRIBUTOR)return be.rsuFuel.tank.isEmpty()?0:be.rsuFuel.tank.getFluidAmount()*rsuKgPerMb(be,be.rsuFuel.tank.getFluid().getFluid());return be.rocket.fuel()*kgPerMb(be,false)+be.rocket.oxidizer()*kgPerMb(be,true);}
 private FuelMassBridge(){}
}
